import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { ApiConfig } from 'lib/api'
import { ApiError, readableErrorMessage } from 'lib/api-error'

import {
    signalsReviewerExclusionsList,
    signalsReviewerExclusionsRevokeCreate,
} from 'products/signals/frontend/generated/api'
import type { ReviewerExclusionApi } from 'products/signals/frontend/generated/api.schemas'

import { captureInboxSettingsChanged } from '../inboxAnalytics'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reviewerExclusionsLogicValues {
    exclusions: ReviewerExclusionApi[] | null
    exclusionsLoading: boolean
    revokingIds: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reviewerExclusionsLogicActions {
    loadExclusions: () => any
    loadExclusionsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadExclusionsSuccess: (
        exclusions: ReviewerExclusionApi[],
        payload?: any
    ) => {
        exclusions: ReviewerExclusionApi[]
        payload?: any
    }
    removeRevokedExclusion: (id: string) => string
    removeRevokedExclusionFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    removeRevokedExclusionSuccess: (
        exclusions: ReviewerExclusionApi[] | null,
        payload?: string
    ) => {
        exclusions: ReviewerExclusionApi[] | null
        payload?: string
    }
    revokeExclusion: (id: string) => {
        id: string
    }
    revokeExclusionSettled: (id: string) => {
        id: string
    }
}

export type reviewerExclusionsLogicType = MakeLogicType<reviewerExclusionsLogicValues, reviewerExclusionsLogicActions>

/**
 * The current user's standing reviewer exclusions: areas where automatic reviewer selection skips
 * them. People add one from the remove-reviewer dialog, and this logic lists and revokes them.
 */
export const reviewerExclusionsLogic = kea<reviewerExclusionsLogicType>([
    path(['scenes', 'inbox', 'logics', 'reviewerExclusionsLogic']),
    actions({
        revokeExclusion: (id: string) => ({ id }),
        revokeExclusionSettled: (id: string) => ({ id }),
    }),
    loaders(({ values }) => ({
        exclusions: [
            null as ReviewerExclusionApi[] | null,
            {
                loadExclusions: async () => {
                    const rows = await signalsReviewerExclusionsList(String(ApiConfig.getCurrentProjectId()))
                    return rows.filter((row) => row.status === 'active')
                },
                removeRevokedExclusion: (id: string) => (values.exclusions ?? []).filter((row) => row.id !== id),
            },
        ],
    })),
    reducers({
        revokingIds: [
            [] as string[],
            {
                revokeExclusion: (state, { id }) => [...state, id],
                revokeExclusionSettled: (state, { id }) => state.filter((existing) => existing !== id),
            },
        ],
    }),
    listeners(({ actions }) => ({
        revokeExclusion: async ({ id }) => {
            let success = true
            try {
                await signalsReviewerExclusionsRevokeCreate(String(ApiConfig.getCurrentProjectId()), id)
                actions.removeRevokedExclusion(id)
            } catch (error) {
                success = false
                lemonToast.error(
                    (error instanceof ApiError && readableErrorMessage(error.data)) ||
                        "Couldn't remove this area. Try again."
                )
            } finally {
                actions.revokeExclusionSettled(id)
                // pinned: analytics setting name — renaming breaks dashboards
                captureInboxSettingsChanged({
                    setting: 'reviewer_exclusion',
                    newValue: 'revoked',
                    success,
                    scope: 'user',
                })
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadExclusions()
    }),
])
